#!/usr/bin/env python3
"""Generate pragma.h from SQLite's mkpragmatab.tcl metadata."""

from __future__ import annotations

import re
import sys
from pathlib import Path


FLAG_MEANING = {
    "NeedSchema": "Force schema load before running",
    "ReadOnly": "Read-only HEADER_VALUE",
    "Result0": "Acts as query when no argument",
    "Result1": "Acts as query when has one argument",
    "SchemaReq": 'Schema required - "main" is default',
    "SchemaOpt": "Schema restricts name search if present",
    "NoColumns": "OP_ResultRow called with zero columns",
    "NoColumns1": "zero columns if RHS argument is present",
}


def ExtractPragmaDef(path: Path) -> str:
    text = path.read_text()
    match = re.search(r"^set pragma_def \{\n(.*?)^\}\n", text, re.MULTILINE | re.DOTALL)
    if not match:
        raise RuntimeError(f"could not find pragma_def block in {path}")
    return match.group(1)


def ParsePragmas(block: str):
    all_by_name = {}
    cols_list: list[tuple[str, ...]] = []
    all_cols: set[tuple[str, ...]] = set()
    col_used_by: dict[tuple[str, ...], list[str]] = {}
    all_flags: set[str] = set()

    name = ""
    typ = ""
    ifs: list[str] = []
    flags: list[str] = []
    cols: tuple[str, ...] | None = None
    arg = "0"

    def record_one() -> None:
        nonlocal name, typ, ifs, flags, cols, arg
        if not name:
            return
        if cols:
            if cols not in all_cols:
                all_cols.add(cols)
                cols_list.append(cols)
            col_used_by.setdefault(cols, []).append(name)
        all_by_name[name] = {
            "type": typ,
            "arg": arg,
            "ifs": tuple(ifs),
            "flags": tuple(flags),
            "cols": cols,
        }
        name = ""
        typ = ""
        ifs = []
        flags = []
        cols = None
        arg = "0"

    for raw_line in block.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if ":" not in line:
            raise RuntimeError(f"bad pragma_def line: {raw_line}")
        ident, val = line.split(":", 1)
        ident = ident.strip()
        val = val.strip()

        if ident == "NAME":
            record_one()
            name = val
            typ = val.upper()
        elif ident == "TYPE":
            typ = val
            if typ == "FLAG":
                flags.extend(["Result0", "NoColumns1"])
        elif ident == "ARG":
            arg = val
        elif ident == "COLS":
            cols = tuple(val.split())
        elif ident == "IF":
            ifs.append(val)
        elif ident == "FLAG":
            for term in val.split():
                flags.append(term)
                all_flags.add(term)
        else:
            raise RuntimeError(f"bad pragma_def line: {raw_line}")

    record_one()
    return all_by_name, cols_list, col_used_by, all_flags


def IfString(ifs: tuple[str, ...]) -> str:
    return " ".join(ifs)


def SortColumnLists(cols_list: list[tuple[str, ...]]) -> list[tuple[str, ...]]:
    return sorted(cols_list, key=lambda cols: (-len(cols), " ".join(cols)))


def Generate(output: Path, tcl_source: Path) -> None:
    all_by_name, cols_list, col_used_by, all_flags = ParsePragmas(ExtractPragmaDef(tcl_source))
    all_names = sorted(all_by_name)

    lines: list[str] = [
        "/* DO NOT EDIT!",
        "** This file is automatically generated by the script at",
        "** ../tool/mkpragmatab.tcl.  To update the set of pragmas, edit",
        "** that script and rerun it.",
        "*/",
        "",
        "/* The various pragma types */",
    ]

    seen_types: set[str] = set()
    pnum = 0
    for name in all_names:
        typ = all_by_name[name]["type"]
        if typ in seen_types:
            continue
        ifs = IfString(all_by_name[name]["ifs"])
        if "SQLITE_DEBUG" in ifs or "SQLITE_HAS_CODEC" in ifs:
            continue
        seen_types.add(typ)
        lines.append(f"#define {'PragTyp_' + typ:<35} {pnum:4d}")
        pnum += 1
    for name in all_names:
        typ = all_by_name[name]["type"]
        if typ in seen_types:
            continue
        ifs = IfString(all_by_name[name]["ifs"])
        if "SQLITE_DEBUG" in ifs:
            continue
        seen_types.add(typ)
        lines.append(f"#define {'PragTyp_' + typ:<35} {pnum:4d}")
        pnum += 1
    for name in all_names:
        typ = all_by_name[name]["type"]
        if typ in seen_types:
            continue
        seen_types.add(typ)
        lines.append(f"#define {'PragTyp_' + typ:<35} {pnum:4d}")
        pnum += 1

    lines.extend(["", "/* Property flags associated with various pragma. */"])
    fv = 1
    for flag in sorted(all_flags):
        meaning = FLAG_MEANING[flag]
        lines.append(f"#define PragFlg_{flag:<10} 0x{fv:02x} /* {meaning} */")
        fv *= 2

    cols_list = SortColumnLists(cols_list)
    lines.extend(
        [
            "",
            "/* Names of columns for pragmas that return multi-column result",
            "** or that return single-column results where the name of the",
            "** result column is different from the name of the pragma",
            "*/",
            "static const char *const pragCName[] = {",
        ]
    )

    offset = 0
    all_col_list: list[str] = []
    cols_offset: dict[tuple[str, ...], int] = {}
    for cols in cols_list:
        n = len(cols)
        limit = len(all_col_list) - n
        reused = False
        for i in range(max(limit, 0)):
            if tuple(all_col_list[i : i + n]) == cols:
                used = " ".join(col_used_by[cols])
                lines.append(f"{'':27s}/* {used} reuses {i} */")
                cols_offset[cols] = i
                reused = True
                break
        if reused:
            continue
        cols_offset[cols] = offset
        used_by = f" /* Used by: {' '.join(col_used_by[cols])} */"
        for col in cols:
            all_col_list.append(col)
            lines.append(f'  /* {offset:3d} */ "{col}",{"":14s}{used_by}')
            used_by = ""
            offset += 1
    lines.append("};")

    lines.extend(
        [
            "",
            "/* Definitions of all built-in pragmas */",
            "typedef struct PragmaName {",
            "  const char *const zName; /* Name of pragma */",
            "  u8 ePragTyp;             /* PragTyp_XXX value */",
            "  u8 mPragFlg;             /* Zero or more PragFlg_XXX values */",
            "  u8 iPragCName;           /* Start of column names in pragCName[] */",
            "  u8 nPragCName;           /* Num of col names. 0 means use pragma name */",
            "  u64 iArg;                /* Extra argument */",
            "} PragmaName;",
            "static const PragmaName aPragmaName[] = {",
        ]
    )

    current_if: tuple[str, ...] = ()
    for name in all_names:
        entry = all_by_name[name]
        typ = entry["type"]
        arg = entry["arg"]
        ifs = entry["ifs"]
        flags = entry["flags"]
        cols = entry["cols"]
        if cols:
            cy = cols_offset[cols]
            nx = len(cols)
        else:
            cy = 0
            nx = 0

        if ifs != current_if:
            if current_if:
                for _ in current_if:
                    lines.append("#endif")
            current_if = ifs
            if current_if:
                for cond in current_if:
                    lines.append(f"#if {cond}")

        flag_expr = "0" if not flags else "PragFlg_" + "|PragFlg_".join(flags)
        lines.extend(
            [
                f' {{/* zName:     */ "{name}",',
                f"  /* ePragTyp:  */ PragTyp_{typ},",
                f"  /* ePragFlg:  */ {flag_expr},",
                f"  /* ColNames:  */ {cy}, {nx},",
                f"  /* iArg:      */ {arg} }},",
            ]
        )

    if current_if:
        for _ in current_if:
            lines.append("#endif")
    lines.append("};")

    all_count = 0
    default_count = 0
    for name in all_names:
        all_count += 1
        ifs = IfString(all_by_name[name]["ifs"])
        if re.search(r"^defined", ifs) or re.search(r"[^!]defined", ifs):
            continue
        default_count += 1
    lines.append(f"/* Number of pragmas: {default_count} on by default, {all_count} total. */")
    output.write_text("\n".join(lines) + "\n")


def main(argv: list[str]) -> int:
    if len(argv) not in (2, 3):
        print("usage: mkpragmatab.py OUT [MKPRAGMATAB_TCL]", file=sys.stderr)
        return 2
    output = Path(argv[1])
    if len(argv) == 3:
        tcl_source = Path(argv[2])
    else:
        tcl_source = Path(__file__).with_name("mkpragmatab.tcl")
    Generate(output, tcl_source)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
